CREATE TABLE [dbo].[ccRIALoading](	  [load_id] INT NOT NULL IDENTITY(1,1)	, [cam_id] SMALLINT NOT NULL	, [loadType] SMALLINT NOT NULL	, [description] VARCHAR(255) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL	, [pctg] SMALLINT NOT NULL DEFAULT((0))	, [loadDate] DATETIME NOT NULL DEFAULT(getdate())	, [upPrepared] BIT NOT NULL DEFAULT((0))	, [camName] VARCHAR(50) COLLATE SQL_Latin1_General_CP1_CI_AS NOT NULL DEFAULT('')	, [state] SMALLINT NOT NULL DEFAULT((0))	, [frame] SMALLINT NOT NULL DEFAULT((0))	, [regsLoaded] INT NOT NULL DEFAULT((0))	, [telsLoaded] INT NOT NULL DEFAULT((0))	, [regsNotLoaded] INT NOT NULL DEFAULT((0))	, [telsNotLoaded] INT NULL DEFAULT((0))	, [regsBlocked] INT NULL DEFAULT((0))	, [telsBlocked] INT NULL DEFAULT((0))	, [alreadyLoaded] INT NULL DEFAULT((0))	, [list_id] INT NULL	, CONSTRAINT [PK_ccRIALoading] PRIMARY KEY ([load_id] ASC))CREATE NONCLUSTERED INDEX [IX_ccRIALoading] ON [dbo].[ccRIALoading] ([loadDate] DESC)CREATE NONCLUSTERED INDEX [IX_ccRIALoading_1] ON [dbo].[ccRIALoading] ([cam_id] DESC, [loadDate] DESC)